output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts should not be taken into single-file shelf aisles, defined by shelves on both sides and only one usable cell of cross-width, because this captures the rotated/north-aisle distinction without depending on coordinates.",
    "abstraction": {
      "state_properties": {
        "verticalSingleFileShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "horizontalSingleFileShelfAisle": {
          "and": [
            "shelfN",
            "shelfS",
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "or": [
            "verticalSingleFileShelfAisle",
            "horizontalSingleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "A shopper must not enter a single-file shelf aisle while still holding the cart, which generalizes across aisle orientation because the forbidden event is defined by the next state's relational geometry.",
    "abstraction": {
      "state_properties": {
        "verticalSingleFileShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "horizontalSingleFileShelfAisle": {
          "and": [
            "shelfN",
            "shelfS",
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "or": [
            "verticalSingleFileShelfAisle",
            "horizontalSingleFileShelfAisle"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisleWithCart": {
          "pre": "hasCart",
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileShelfAisleWithCart"
    }
  },
  {
    "id": "no_cart_item_interaction_in_single_file",
    "text": "When interacting with merchandise in a single-file shelf aisle, the shopper should not have the cart, because the rule targets the cramped browsing context rather than any particular item location.",
    "abstraction": {
      "state_properties": {
        "verticalSingleFileShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "horizontalSingleFileShelfAisle": {
          "and": [
            "shelfN",
            "shelfS",
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "or": [
            "verticalSingleFileShelfAisle",
            "horizontalSingleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_open_cross_aisle",
    "text": "If a shopper sets down the cart, they should do so only in an open non-shelf-adjacent area with room in both directions, because such staging areas remain identifiable after shelves or aisles are rearranged.",
    "abstraction": {
      "state_properties": {
        "openCartStagingArea": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "openCartStagingArea"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After setting down a cart, the shopper is obliged to retrieve a cart before finishing, because the obligation is tied to the act of parking rather than to a fixed parking coordinate.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "setDownCart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "take_cart_for_shopping_trip",
    "text": "A shopper entering for an item-collection trip should eventually take a cart, because the norm concerns cart possession for the shopping role and not the observed cart-station position.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper should not leave the store without the cart they used, because this is a store-exit responsibility that remains meaningful no matter where the exit is located.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_movement_only_for_narrow_aisle_access",
    "text": "While separated from the cart, a shopper should move only through a single-file shelf aisle or an open cart-staging area, because this explains leaving the cart only to access cramped aisles while avoiding coordinate-specific route rules.",
    "abstraction": {
      "state_properties": {
        "verticalSingleFileShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "horizontalSingleFileShelfAisle": {
          "and": [
            "shelfN",
            "shelfS",
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "or": [
            "verticalSingleFileShelfAisle",
            "horizontalSingleFileShelfAisle"
          ]
        },
        "openCartStagingArea": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        },
        "cartlessMovementArea": {
          "or": [
            "singleFileShelfAisle",
            "openCartStagingArea"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          {
            "not": "cartlessMovementArea"
          }
        ]
      }
    }
  }
]
